    ---------------------------------------------------------------------------
    -- Legion / order hall — verified guides (WowDB/Wowhead/Wowpedia/wow-pro)
    ---------------------------------------------------------------------------
    [131812] = { name = "Darkshard Fragment", sourceType = "VENDOR", zone = "Highmountain", coords = "38.6, 45.8", target = "Ransa Greyfeather (Thunder Totem, upper ring)", cost = "500 gold (Revered with Highmountain Tribe)", difficulty = "Easy", guide = "1. Earn Revered reputation with the Highmountain Tribe.\n2. Fly to Thunder Totem in Highmountain.\n3. Find Ransa Greyfeather on the upper ring at 38.6, 45.8.\n4. Buy the Darkshard Fragment for 500 gold.\n5. Use it to nibble a piece of the crystal (5 min cooldown).", waypoint = "/way Highmountain 38.6 45.8 Ransa Greyfeather (Thunder Totem)" },
    [129093] = { name = "Ravenbear Disguise", sourceType = "QUEST", zone = "Stormheim", coords = "33.9, 34.7", target = "Spymaster Illandris and Spymaster Shwayder (Blackbeak Overlook)", cost = "Free (quest reward: Masters of Disguise)", difficulty = "Easy", guide = "1. The quest Masters of Disguise is automatically offered by the Forsaken Bat-Rider while flying over Stormheim.\n2. Fly to Blackbeak Overlook at 33.9, 34.7.\n3. Slay Spymaster Illandris and Spymaster Shwayder.\n4. Turn in the quest to receive the Ravenbear Disguise toy.", waypoint = "/way Stormheim 33.9 34.7 Blackbeak Overlook" },
    [208798] = { name = "Recorded Memories of Tyr's Guard", sourceType = "QUEST", zone = "Thaldraszus", coords = "60.1, 58.7", target = "Titan console at the top of Tyrhold (quest: Disc Delivery)", cost = "Free (quest reward)", difficulty = "Easy", guide = "1. Progress the Tyr questline in Thaldraszus until the quest Disc Delivery (from Nozdormu) is available.\n2. Fly to the top of Tyrhold at 60.1, 58.7.\n3. Insert the Disc of Tyr into the titan console.\n4. Complete the quest to receive the toy (usable only in Tyrhold).", waypoint = "/way Thaldraszus 60.1 58.7 Tyrhold titan console" },
    [130169] = { name = "Tournament Favor", sourceType = "OTHER", zone = "Class Order Hall", coords = "", target = "Class Hall mission table (mission: Win the Crowd)", cost = "Free (mission reward)", difficulty = "Medium", guide = "1. Build and upgrade the mission table in your Class Order Hall.\n2. Run the level 110 mission 'Win the Crowd' (requires followers at about 760 item level).\n3. On success the Tournament Favor toy is awarded as a mission reward.\n4. Use it to wave the favor and be the envy of all around you (10 min cooldown).", waypoint = "" },
    [130191] = { name = "Trapped Treasure Chest Kit", sourceType = "VENDOR", zone = "Azsuna", coords = "48.2, 73.8", target = "Marin Bladewing (Wardens' Redoubt, Isle of the Watchers)", cost = "200 gold (Honored with The Wardens)", difficulty = "Easy", guide = "1. Earn Honored reputation with The Wardens.\n2. Travel to the Isle of the Watchers in Azsuna at 48.2, 73.8.\n3. Buy the Trapped Treasure Chest Kit from Marin Bladewing for 200 gold.\n4. Use it to summon an Innocent Looking Treasure Chest.", waypoint = "/way Azsuna 48.2 73.8 Marin Bladewing" },
    [152556] = { name = "Trawler Totem", sourceType = "VENDOR", zone = "Highmountain", coords = "32.6, 40.8", target = "Akule Riverhorn (canoe in the river west of Thunder Totem)", cost = "500 gold (Good Friend with Akule Riverhorn)", difficulty = "Easy", guide = "1. Raise your friendship with Akule Riverhorn to Good Friend by fishing up items near his boat.\n2. He stands on a small canoe west of Thunder Totem at 32.6, 40.8.\n3. Buy the Trawler Totem from him for 500 gold.\n4. Use it to summon a totem that grants +4 Fishing skill to nearby players for 2 min.", waypoint = "/way Highmountain 32.6 40.8 Akule Riverhorn (boat)" },
    [130214] = { name = "Worn Doll", sourceType = "LOOT", zone = "Val'sharah", coords = "34.4, 59.3", target = "Mad Henryk (Haunted Manor) / Ravenous Stormcrow", cost = "Free", difficulty = "Easy", guide = "1. Travel to the Haunted Manor west of Bradensbrook in Val'sharah at 34.4, 59.3.\n2. Kill Mad Henryk (the doll also drops from Ravenous Stormcrows in Val'sharah).\n3. Loot the Worn Doll.\n4. Use it to place a doll on the ground that follows you for 1 minute (20 min cooldown).", waypoint = "/way Val'sharah 34.4 59.3 Haunted Manor (Mad Henryk)" },
    [129055] = { name = "Shoe Shine Kit", sourceType = "TREASURE", zone = "Dalaran (Broken Isles)", coords = "44.0, 49.0", target = "Sheddle's Chest (upstairs of the Photonic Playground)", cost = "Free", difficulty = "Easy", guide = "1. Go to Dalaran over the Broken Isles and enter the Photonic Playground next to the Wonderworks at 44.0, 49.0.\n2. Go upstairs: Sheddle's Chest spawns every Saturday night at midnight (server time) and despawns 2 hours later.\n3. Loot the chest to get the Shoe Shine Kit.\n4. Use it to get a free shoe shine (10 min cooldown).", waypoint = "/way Dalaran 44.0 49.0 Photonic Playground (upstairs)" },
    [140309] = { name = "Prismatic Bauble", sourceType = "VENDOR", zone = "Dalaran (Broken Isles)", coords = "44.6, 46.2", target = "The Mad Merchant (spawns at the Wonderworks toy shop)", cost = "250,000 gold", difficulty = "Medium", guide = "1. The Mad Merchant occasionally appears at the Wonderworks toy shop in Dalaran at 44.6, 46.2, staying for about an hour.\n2. Visit the shop until he spawns.\n3. Buy the Prismatic Bauble for 250,000 gold.\n4. Use it for a prismatic light show (2 min cooldown).", waypoint = "/way Dalaran 44.6 46.2 The Wonderworks (The Mad Merchant)" },
    [141331] = { name = "Vial of Green Goo", sourceType = "LOOT", zone = "Dun Morogh (Gnomeregan)", coords = "17.7, 39.2", target = "Endgineer Omegaplugg (secret boss in Tinkers' Court)", cost = "Free", difficulty = "Medium", guide = "1. Enter Gnomeregan in Dun Morogh at 17.7, 39.2.\n2. Clear the dungeon to the Tinkers' Court and defeat Mekgineer Thermaplugg.\n3. The secret boss Endgineer Omegaplugg then spawns — defeat him with a max-level group.\n4. Loot the Vial of Green Goo (transforms you into a Leper Gnome).", waypoint = "/way Dun Morogh 17.7 39.2 Gnomeregan entrance" },
    [130147] = { name = "Thistleleaf Branch", sourceType = "TREASURE", zone = "Val'sharah", coords = "55.6, 77.6", target = "Unguarded Thistleleaf Treasure (Field of Dreamers)", cost = "Free", difficulty = "Easy", guide = "1. Fly to the Field of Dreamers in Val'sharah at 55.6, 77.6.\n2. Loot the small Unguarded Thistleleaf Treasure chest.\n3. Five Thistleleaf Rascals spawn and attack — defeat them.\n4. The chest contains the Thistleleaf Branch toy.", waypoint = "/way Val'sharah 55.6 77.6 Unguarded Thistleleaf Treasure" },
    [133542] = { name = "Tosselwrench's Mega-Accurate Simulation Viewfinder", sourceType = "VENDOR", zone = "Orgrimmar", coords = "52.4, 41.0", target = "Kiatke (Cataclysm Timewalking vendor, Western Earthshrine)", cost = "1,500 Timewarped Badges", difficulty = "Easy", guide = "1. Queue for Cataclysm Timewalking dungeons and earn Timewarped Badges.\n2. During Cataclysm Timewalking weeks, find Kiatke near the Western Earthshrine in Orgrimmar at 52.4, 41.0 (Horde) or the Eastern Earthshrine in Stormwind City (Alliance).\n3. Buy the Viewfinder for 1,500 Timewarped Badges.\n4. Use it to witness the wrath of Deathwing firsthand in a simulation.", waypoint = "/way Orgrimmar 52.4 41.0 Kiatke (Western Earthshrine)" },
    [140314] = { name = "Crab Shank", sourceType = "LOOT", zone = "Suramar", coords = "66.7, 67.1", target = "Pinchshank (rare crab on the beach)", cost = "Free", difficulty = "Easy", guide = "1. Travel to the beach outside the Estate of the First Arcanist in Suramar at 66.7, 67.1.\n2. Find and kill the rare crab Pinchshank.\n3. Loot the Crab Shank toy.\n4. Use it to give your hunter crab pet a knife (5 min cooldown).", waypoint = "/way Suramar 66.7 67.1 Pinchshank" },
    [147867] = { name = "Pilfered Sweeper", sourceType = "TREASURE", zone = "Broken Shore", coords = "47.8, 67.3", target = "Curious Wyrmtongue Cache (Secret Treasure Lair, Soldier's Torment)", cost = "Free (needs Wyrmtongue's Cache Key)", difficulty = "Medium", guide = "1. Get a Wyrmtongue's Cache Key: complete the Excavator Karla quest chain or buy it from Treasure Master Iks'reeged for 2,000 Nethershards.\n2. In Soldier's Torment on the Broken Shore at 47.8, 67.3, click the Peculiar Rope next to the 'Nothing Secret Here!' sign.\n3. Inside the Secret Treasure Lair, open a Curious Wyrmtongue Cache with the key.\n4. Loot the Pilfered Sweeper toy from the cache.", waypoint = "/way Broken Shore 47.8 67.3 Secret Treasure Lair rope" },
    [142494] = { name = "Purple Blossom", sourceType = "QUEST", zone = "Dalaran (Broken Isles)", coords = "57.1, 53.5", target = "Aerith Primrose (flower vendor outside the Violet Hold)", cost = "4g 79s (quest item)", difficulty = "Easy", guide = "1. In Dalaran over the Broken Isles, find Aerith Primrose outside the Violet Hold at 57.1, 53.5.\n2. Buy a Purple Blossom (quest item) from her.\n3. With a Bloodgazer Hatchling pet summoned, use the blossom to begin the Bloodgazer Bonding quest.\n4. Complete the quest to receive the Purple Blossom toy.", waypoint = "/way Dalaran 57.1 53.5 Aerith Primrose" },
    [143727] = { name = "Champion's Salute", sourceType = "VENDOR", zone = "Class Order Hall", coords = "", target = "Class Hall quartermaster / collectibles vendor", cost = "1,000 gold", difficulty = "Easy", guide = "1. Travel to your Class Order Hall via the portal in Dalaran over the Broken Isles.\n2. Find your class quartermaster (collectibles vendor).\n3. Buy the Champion's Salute for 1,000 gold.\n4. Use it to strike a heroic pose under a beacon of light (30 min cooldown).", waypoint = "" },
    [147307] = { name = "Crate of Bobbers: Carved Wooden Helm", sourceType = "VENDOR", zone = "Stormheim", coords = "89.0, 9.0", target = "Corbyn (raven at the easternmost point of Shield's Rest island)", cost = "100 Shiny Baubles (Best Friend with Corbyn)", difficulty = "Easy", guide = "1. Raise your friendship with Corbyn to Best Friend by fishing Shiny Baubles in the waters in front of him.\n2. Corbyn perches on the eastern tip of Shield's Rest, off the northeastern coast of Stormheim, at 89.0, 9.0.\n3. Buy the Crate of Bobbers: Carved Wooden Helm for 100 Shiny Baubles.\n4. Open the crate to put a carved wooden helm on your fishing bobber.", waypoint = "/way Stormheim 89.0 9.0 Shield's Rest (Corbyn)" },
    [151016] = { name = "Fractured Necrolyte Skull", sourceType = "VENDOR", zone = "Shattrath City", coords = "54.0, 39.0", target = "Cupri (TBC Timewalking vendor, Terrace of Light upper level)", cost = "750 Timewarped Badges", difficulty = "Easy", guide = "1. Queue for Burning Crusade Timewalking dungeons and earn Timewarped Badges.\n2. During TBC Timewalking weeks, enter the Terrace of Light in Shattrath City and go to the upper level at 54.0, 39.0.\n3. Buy the Fractured Necrolyte Skull from Cupri for 750 Timewarped Badges.\n4. Use it to sacrifice a critter soul and open a portal to the Black Temple (1 hour cooldown).", waypoint = "/way Shattrath City 54.0 39.0 Cupri (Terrace of Light)" },

