    -- Dragonflight II — verified guides (toys only; mounts/currencies/knowledge filtered out)
    ---------------------------------------------------------------------------
    [198206] = { name = "Environmental Emulator", sourceType = "PROFESSION", zone = "The Waking Shores", coords = "47.0, 82.0", target = "Dragon Isles Engineering trainer (Dragonscale Basecamp)", cost = "Engineering materials", difficulty = "Easy", guide = "1. Learn Dragon Isles Engineering from the profession trainer at Dragonscale Basecamp.\n2. The Environmental Emulator recipe is learned with Dragon Isles Engineering.\n3. Craft it with the reagents listed in the recipe.\n4. Use the toy outside to place an emulator that lets your party view the world from another perspective.", waypoint = "/way The Waking Shores 47.0 82.0 Dragonscale Basecamp Engineering trainer" },
    [200640] = { name = "Obsidian Egg Clutch", sourceType = "VENDOR", zone = "The Waking Shores", coords = "24.6, 56.8", target = "Samia Inkling (Sabellian's Quartermaster) or Xaldrass, Obsidian Throne", cost = "1 Primal Bear Spine + 1 Large Sturdy Femur + 100 Dragon Isles Supplies", difficulty = "Easy", guide = "1. Travel to the Obsidian Throne in the Obsidian Citadel, western The Waking Shores.\n2. Requires being considered a Cohort by Sabellian.\n3. Buy the Obsidian Egg Clutch from Samia Inkling (upper area) or Xaldrass (middle floor).\n4. Use the toy to place three obsidian dragon eggs ready to hatch.", waypoint = "/way The Waking Shores 24.6 56.8 Obsidian Throne (Samia Inkling)" },
    [200876] = { name = "Yennu's Toy Boat", sourceType = "TREASURE", zone = "Ohn'ahran Plains", coords = "52.4, 61.0", target = "Tuskarr Toy Boat near Yennu (Thunderspine Thicket)", cost = "Free", difficulty = "Easy", guide = "1. Search the Tuskarr Toy Boat objects in the Ohn'ahran Plains near Yennu in Thunderspine Thicket.\n2. Loot the boat to receive Yennu's Toy Boat.\n3. Return the toy boat to Yennu nearby to complete the quest.", waypoint = "/way Ohn'ahran Plains 52.4 61.0 Tuskarr Toy Boat (Thunderspine Thicket)" },
    [202019] = { name = "Golden Dragon Goblet", sourceType = "TREASURE", zone = "The Waking Shores", coords = "65.8, 41.8", target = "Golden Dragon Goblet (treasure object)", cost = "Free", difficulty = "Easy", guide = "1. Buy the Archeologist Artifact Notes map from Cataloger Jakes at Dragonscale Basecamp (47.0, 82.0).\n2. Use the map to reveal the dig site in The Waking Shores.\n3. Fly to 65.8, 41.8 and loot the Golden Dragon Goblet from the pile of gold.\n4. The toy leaves riches in your wake when used.", waypoint = "/way The Waking Shores 65.8 41.8 Golden Dragon Goblet" },
    [203722] = { name = "Experimental Dragon Pack", sourceType = "TREASURE", zone = "The Forbidden Reach", coords = "35.8, 48.0", target = "Experimental Dragon Pack object near Prototype Tinker-Tron (Zskera Vaults)", cost = "Free", difficulty = "Easy", guide = "1. Enter the Zskera Vaults through the broken portal in the Worldbreaker area of The Forbidden Reach.\n2. Clear rooms with Zskera Vaults keys until you find the room with the Prototype Tinker-Tron.\n3. Loot the Experimental Dragon Pack objects scattered near the Tinker-Tron.\n4. The pack propels you forward in the air (works in the Zskera Vaults and The Forbidden Reach).", waypoint = "/way The Forbidden Reach 35.8 48.0 Zskera Vaults entrance portal" },
    [203757] = { name = "Brazier of Madness", sourceType = "TREASURE", zone = "Zul'Gurub", coords = "61.7, 45.8", target = "Brazier of Madness (Cache of Madness, north side of the altar)", cost = "Free", difficulty = "Medium", guide = "1. Complete the achievement Relics of a Fallen Empire in Zul'Gurub (Dragonflight discovery).\n2. Enter Zul'Gurub and make your way to the Cache of Madness.\n3. Loot the Brazier of Madness on the north side of the altar at 61.7, 45.8.\n4. Use the toy to place a brazier that enables cooking for anyone nearby.", waypoint = "/way Zul'Gurub 61.7 45.8 Cache of Madness (Brazier of Madness)" },
    [203852] = { name = "Spore-Bound Essence", sourceType = "TREASURE", zone = "The Forbidden Reach", coords = "35.8, 48.0", target = "Overgrown Skeleton (bone room inside the Zskera Vaults)", cost = "Free", difficulty = "Easy", guide = "1. Enter the Zskera Vaults via the broken portal in The Forbidden Reach.\n2. Unlock doors with Zskera Vaults keys until you reach the room full of bone piles.\n3. Loot the Overgrown Skeleton to receive the Spore-Bound Essence.\n4. Consume the spores to transform (60 min cooldown).", waypoint = "/way The Forbidden Reach 35.8 48.0 Zskera Vaults entrance portal" },
    [204256] = { name = "Holoviewer: The Scarlet Queen", sourceType = "TREASURE", zone = "The Forbidden Reach", coords = "35.8, 48.0", target = "Chest inside the Zskera Vaults", cost = "Free", difficulty = "Easy", guide = "1. Enter the Zskera Vaults via the broken portal in The Forbidden Reach.\n2. Collect Zskera Vaults keys from rares, events and chests in The Forbidden Reach to unlock doors.\n3. Loot the chest that contains the Holoviewer: The Scarlet Queen.\n4. Use the toy to create a holographic tribute of Alexstrasza.", waypoint = "/way The Forbidden Reach 35.8 48.0 Zskera Vaults entrance portal" },
    [204389] = { name = "Stone Breaker", sourceType = "QUEST", zone = "Zaralek Cavern", coords = "64.7, 37.6", target = "Quest The Patience of Princes (Embers of Neltharion campaign, ends at Elder Honeypelt)", cost = "Quest reward", difficulty = "Easy", guide = "1. The quest starts from Sabellian at 87.4, 27.5 in the Ohn'ahran Plains during the Embers of Neltharion campaign.\n2. Progress through the Zaralek Cavern campaign chapter quests.\n3. Complete The Patience of Princes, which ends at Elder Honeypelt at 64.7, 37.6 in Zaralek Cavern.\n4. The Stone Breaker toy is a guaranteed quest reward.", waypoint = "/way Zaralek Cavern 64.7 37.6 Elder Honeypelt (The Patience of Princes)" },
    [204481] = { name = "Morqut Hearth Totem", sourceType = "VENDOR", zone = "The Forbidden Reach", coords = "34.2, 60.0", target = "Turik (Morqut Village)", cost = "2,000 Elemental Overflow", difficulty = "Easy", guide = "1. Travel to Morqut Village in The Forbidden Reach.\n2. Speak with Turik at 34.2, 60.0.\n3. Buy the Morqut Hearth Totem for 2,000 Elemental Overflow (zone currency).\n4. Use it while in The Forbidden Reach to teleport to Morqut Village (5 charges).", waypoint = "/way The Forbidden Reach 34.2 60.0 Turik (Morqut Village)" },
    [204687] = { name = "Obsidian Battle Horn", sourceType = "TREASURE", zone = "The Forbidden Reach", coords = "35.8, 48.0", target = "Chests inside the Zskera Vaults", cost = "Free", difficulty = "Easy", guide = "1. Enter the Zskera Vaults via the broken portal in The Forbidden Reach.\n2. Farm Zskera Vaults keys from rares, Forbidden Hoard events and chests in The Forbidden Reach.\n3. Open doors and loot chests until the Obsidian Battle Horn drops.\n4. Blow the horn to signal attacks (1 min cooldown).", waypoint = "/way The Forbidden Reach 35.8 48.0 Zskera Vaults entrance portal" },
    [205688] = { name = "Glutinous Glitterscale Glob", sourceType = "QUEST", zone = "Zaralek Cavern", coords = "62.5, 70.2", target = "World Quest All That Glitter (near Sundered Flame Camp / Nal ks'kol)", cost = "Free", difficulty = "Easy", guide = "1. Wait for the world quest All That Glitter to be active in Zaralek Cavern (given near Sundered Flame Camp).\n2. Fly to the quest area near Nal ks'kol in southeastern Zaralek Cavern.\n3. Complete the quest by collecting the sparkliest glitter from moths.\n4. The Glutinous Glitterscale Glob is a hidden bonus reward with a low chance.", waypoint = "/way Zaralek Cavern 62.5 70.2 All That Glitter WQ (near Nal ks'kol)" },
    [206043] = { name = "Fyrakk's Frenzy", sourceType = "LOOT", zone = "The Azure Span", coords = "55.4, 35.2", target = "Shadeisethal (Fyrakk Assault boss, Suffusion Camp: Frostburn)", cost = "Free", difficulty = "Farm", guide = "1. Wait for the Fyrakk Assault world event in the Azure Span (Suffusion Camp: Frostburn at 55.4, 35.2) or other Dragon Isles zones.\n2. Complete the assault up to stage 3 and defeat Fyrakk's Disciple (Shadeisethal).\n3. Loot the disciple - Fyrakk's Frenzy has a low drop rate (~3%).\n4. Use the toy to summon Fyrakk's essence and devastate critters with a deep breath.", waypoint = "/way The Azure Span 55.4 35.2 Suffusion Camp Frostburn (Shadeisethal)" },
