        sourceType = "TREASURE",
        zone = "Hallowfall",
        coords = "57.5, 27.4",
        target = "Illuminated Footlocker (chest inside the dark cave at 58.4, 27.2 — requires the Glimmering Illumination buff)",
        cost = "Free",
        difficulty = "Medium",
        guide = "1. Travel to the cave entrance northeast of Hallowfall (57.5, 27.4).\n2. Inside the cave it is dark: catch the 5 light motes emitted by the moth (glowing wisp) to get the Glimmering Illumination buff (2 min).\n3. With the buff active, the Illuminated Footlocker becomes visible at the back of the cave (58.4, 27.2).\n4. Open the chest to receive the Cave Spelunker's Torch.\n5. Use it to light a torch (useful in dark caves).",
