    },
    [224554] = {
        name = "Silver Linin' Scepter",
        sourceType = "TREASURE",
        zone = "Hallowfall",
        coords = "45.9, 45.1",
        target = "Sunken Cache (sunken chest off the coast of Mereldar — requires talking to the 4 Sky Captains first)",
        cost = "Free",
        difficulty = "Medium",
        guide = "1. Talk to the 4 Sky Captains patrolling Hallowfall by zeppelin: Clairmonte, Dornald, Onaro and Aerthin — aboard their ships.\n2. After talking to all of them, swim down to the bottom of the bay off Mereldar (45.9, 45.1).\n3. The Sunken Cache becomes lootable underwater.\n4. Open the chest to receive the Silver Linin' Scepter.\n5. Use it to call the wind to your arms — your feet don't touch the ground!",
        waypoint = "/way Hallowfall 45.9 45.1 Sunken Cache"
    },
    [209858] = {
        name = "Dreamsurge Remnant",
        sourceType = "EVENT",
        zone = "The Waking Shores",
        coords = "58.4, 67.8",
        target = "Celestine of the Harvest (rotates weekly among The Waking Shores, Ohn'ahran Plains, The Azure Span and Thaldraszus — in the right week she is at 58.4, 67.8)",
        cost = "500 Dreamsurge Coalescence",
        difficulty = "Easy",
        guide = "1. The Dreamsurge event happens in one Dragon Isles zone per week — check the in-game map for the active zone (the event icon marks the location).\n2. In The Waking Shores week, Celestine of the Harvest is at (58.4, 67.8).\n3. Complete the Dreamsurge objectives in that zone to earn Dreamsurge Coalescence.\n4. Talk to Celestine and buy the Dreamsurge Remnant for 500 Coalescence.\n5. Use it to relive the memory of a Dreamsurge.",
        waypoint = "/way The Waking Shores 58.4 67.8 Celestine of the Harvest"
    },

