    [134022] = { name = "Burgy Blackheart's Handsome Hat", sourceType = "LOOT", zone = "Vashj'ir", coords = "57.0, 70.0", target = "Burgy Blackheart", cost = "Free", difficulty = "Easy", guide = "1. Travel to the Shimmering Expanse in Vashj'ir, just south of Nespirah.\n2. Find the ghost rare Burgy Blackheart at 57.0, 70.0.\n3. Kill him for the guaranteed Burgy Blackheart's Handsome Hat.", waypoint = "/way Vashj'ir 57.0 70.0 Burgy Blackheart" },
    [122304] = { name = "Fandral's Seed Pouch", sourceType = "LOOT", zone = "Firelands", coords = "47.5, 79.6", target = "Majordomo Staghelm", cost = "Free", difficulty = "Easy", guide = "1. Note: this toy requires a Druid character.\n2. Enter the Firelands raid through the portal in Mount Hyjal at 47.5, 79.6.\n3. Defeat Majordomo Staghelm for a chance at Fandral's Seed Pouch. Easily soloable at max level.", waypoint = "/way Firelands 47.5 79.6 Majordomo Staghelm" },
    [174874] = { name = "Budget K'thir Disguise", sourceType = "LOOT", zone = "Uldum", coords = "55.2, 79.3", target = "Yiphrim the Will Ravager", cost = "Free", difficulty = "Medium", guide = "1. Wait for a Black Empire Assault event to be active in Uldum.\n2. East of Neferset City, complete the Summoning Portal event at 55.2, 79.3.\n3. Kill Yiphrim the Will Ravager if he spawns for a chance at the Budget K'thir Disguise.", waypoint = "/way Uldum 55.2 79.3 Yiphrim summoning portal (Neferset)" },
    [169303] = { name = "Hell-Bent Bracers", sourceType = "LOOT", zone = "Uldum", coords = "49.3, 82.3", target = "The Grand Executor", cost = "Free", difficulty = "Medium", guide = "1. During a Black Empire Assault in Uldum, head to the floating platform above Neferset at 49.3, 82.3.\n2. Kill the rare elite The Grand Executor.\n3. Loot the Hell-Bent Bracers.", waypoint = "/way Uldum 49.3 82.3 The Grand Executor (floating platform)" },

    ---------------------------------------------------------------------------
    -- Shadowlands / Nazjatar / Korthia — treasures, rares and vendors (verified: WowDB/Wowhead/Wowpedia/wow-pro/icy-veins)
    ---------------------------------------------------------------------------
    [180993] = { name = "Bat Visage Bobber", sourceType = "LOOT", zone = "Revendreth", coords = "73.6, 75.4", target = "Muckribbon (Rare, summoned via the Forgotten Angler's Rod)", cost = "Free", difficulty = "Farm", guide = "1. Travel to the Forgotten Angler's Rod at 73.6, 75.4 in southeastern Revendreth.\n2. Click the rod to summon the rare Muckribbon (level 58-60).\n3. Defeat Muckribbon — the Bat Visage Bobber has a chance to drop.\n4. If it does not drop, wait for the rare to respawn and try again.", waypoint = "/way Revendreth 73.6 75.4 Forgotten Angler's Rod" },
    [184318] = { name = "Battlecry of Krexus", sourceType = "TREASURE", zone = "Maldraxxus", coords = "44.1, 40.0", target = "Blackhound Cache (Blackhound Outpost)", cost = "Free", difficulty = "Medium", guide = "1. Go to the Blackhound Outpost in northern Maldraxxus (44.1, 40.0).\n2. The cache is sealed: join the Visectus escort event when it starts.\n3. Once Visectus destroys the outpost gate, enter and loot the Blackhound Cache.\n4. The Battlecry of Krexus is inside the cache.", waypoint = "/way Maldraxxus 44.1 40.0 Blackhound Cache" },
    [183986] = { name = "Bondable Sinstone", sourceType = "TREASURE", zone = "Revendreth", coords = "62.9, 72.3", target = "Taskmaster's Trove (Feeders' Thicket)", cost = "Free", difficulty = "Very Easy", guide = "1. Go to the Feeders' Thicket in southeastern Revendreth (62.9, 72.3).\n2. Interact with the Ingress and Egress Rites beside the Taskmaster's Trove.\n3. Dodge the floating orbs while the ritual channels.\n4. Loot the Taskmaster's Trove before you are knocked away to get the Bondable Sinstone.", waypoint = "/way Revendreth 62.9 72.3 Taskmaster's Trove" },
    [184447] = { name = "Kevin's Party Supplies", sourceType = "TREASURE", zone = "Maldraxxus", coords = "65.0, 82.1", target = "Slime-Coated Crate (House of Plagues)", cost = "Free", difficulty = "Very Easy", guide = "1. Head to the House of Plagues in Maldraxxus (65.0, 82.1); Slime-Coated Crates spawn at several spots around it.\n2. Look for the slime-covered chest among the plague pools.\n3. Loot the Slime-Coated Crate to receive Kevin's Party Supplies.", waypoint = "/way Maldraxxus 65.0 82.1 Slime-Coated Crate" },
    [182729] = { name = "Hearty Dragon Plume", sourceType = "TREASURE", zone = "Ardenweald", coords = "48.2, 39.3", target = "Hearty Dragon Plume (roots of Tirna Eas, Glitterfall Heights)", cost = "Free", difficulty = "Easy", guide = "1. Fly to Tirna Eas at Glitterfall Heights in Ardenweald (48.2, 39.3).\n2. Get above the tree, using a glider or Slow Fall.\n3. Drop down onto the roots where the Hearty Dragon Plume rests and loot it.", waypoint = "/way Ardenweald 48.2 39.3 Hearty Dragon Plume" },
    [187051] = { name = "Forgotten Feather", sourceType = "TREASURE", zone = "Korthia", coords = "69.0, 29.9", target = "Forgotten Feather (floating island SE of the Keeper's Respite)", cost = "Free", difficulty = "Easy", guide = "1. Go to the Keeper's Respite in northeastern Korthia and find the path at 63.9, 28.9.\n2. Use a Goblin Glider Kit or Slow Fall to reach the floating island at 69.0, 29.9.\n3. Loot the Forgotten Feather on the island.", waypoint = "/way Korthia 69.0 29.9 Forgotten Feather" },
    [170198] = { name = "Eternal Palace Dining Set", sourceType = "TREASURE", zone = "Nazjatar", coords = "44.8, 48.9", target = "Arcane Chest", cost = "Free", difficulty = "Easy", guide = "1. Travel to Nazjatar via the portal in your faction capital (Boralus or Dazar'alor).\n2. Open Arcane Chests scattered around the zone (for example at 44.8, 48.9).\n3. The Eternal Palace Dining Set is looted from an Arcane Chest.", waypoint = "/way Nazjatar 44.8 48.9 Arcane Chest" },
    [170204] = { name = "Symbol of Gral", sourceType = "VENDOR", zone = "Nazjatar", coords = "37.9, 55.8", target = "Artisan Okata (Mezzamere) / Finder Pruc (Newhome, 49.2, 62.2)", cost = "75 Prismatic Manapearl", difficulty = "Easy", guide = "1. Unlock Nazjatar by completing the intro questline.\n2. Visit Artisan Okata in Mezzamere (37.9, 55.8) or Finder Pruc in Newhome (49.2, 62.2).\n3. Buy the Symbol of Gral for 75 Prismatic Manapearls.", waypoint = "/way Nazjatar 37.9 55.8 Artisan Okata" },
    [184449] = { name = "Jiggles's Favorite Toy", sourceType = "ACHIEVEMENT", zone = "Maldraxxus", coords = "64.9, 22.3", target = "Nine Afterlives (pet all 9 slime cats in Maldraxxus)", cost = "Achievement Reward", difficulty = "Medium", guide = "1. Travel to Maldraxxus.\n2. Find and pet all 9 slime cats scattered around the zone (for example Mr. Jigglesworth at 64.9, 22.3).\n3. Completing the Nine Afterlives achievement rewards Jiggles's Favorite Toy.", waypoint = "/way Maldraxxus 64.9 22.3 Slime Cats (Nine Afterlives)" },
    [183900] = { name = "Sinvyr Tea Set", sourceType = "VENDOR", zone = "Revendreth", coords = "61.3, 63.8", target = "Mistress Mihaela (Sinposium, Darkhaven)", cost = "1,350 gold (requires Honored with Court of Harvesters)", difficulty = "Medium", guide = "1. Reach Honored reputation with the Court of Harvesters in Revendreth.\n2. Travel to Darkhaven and enter the Sinposium (61.3, 63.8).\n3. Buy the Sinvyr Tea Set from quartermaster Mistress Mihaela for 1,350 gold.", waypoint = "/way Revendreth 61.3 63.8 Mistress Mihaela" },
    [186973] = { name = "Anima-ted Leash", sourceType = "PROFESSION", zone = "Oribos", coords = "60.0, 72.0", target = "Keeper Ta'hult (Hall of Curiosities) — Formula: Anima-ted Leash", cost = "15 Polished Pet Charm + enchanting materials", difficulty = "Easy", guide = "1. Learn Shadowlands Enchanting (skill 40 or higher).\n2. Buy the Formula: Anima-ted Leash from Keeper Ta'hult in the Hall of Curiosities, Oribos (60.0, 72.0) for 15 Polished Pet Charm.\n3. Craft the Anima-ted Leash with enchanting materials.", waypoint = "/way Oribos 60.0 72.0 Keeper Ta'hult" },
    [190177] = { name = "Sphere of Enlightened Cogitation", sourceType = "OTHER", zone = "Zereth Mortis", coords = "34.0, 64.0", target = "Enlightened Broker Supplies (paragon cache from Supplies of the Enlightened, Vilo at Haven)", cost = "Free (requires 10,000 paragon reputation with The Enlightened)", difficulty = "Farm", guide = "1. In Zereth Mortis, earn reputation with The Enlightened via world quests, the campaign and the daily quest.\n2. Once you reach the paragon threshold (10,000 rep past Exalted), speak with Vilo at Haven (34.0, 64.0).\n3. Loot the Enlightened Broker Supplies — the Sphere of Enlightened Cogitation has a chance to be inside.", waypoint = "/way Zereth Mortis 34.0 64.0 Vilo" },
,

    ---------------------------------------------------------------------------
    -- Dragonflight / TWW treasures, rares and vendors (verified: Wowhead/WowDB/Wowpedia + HandyNotes pins dataset)
    ---------------------------------------------------------------------------
    [205419] = { name = "Dinn's Drum", sourceType = "LOOT", zone = "Zaralek Cavern", coords = "28.5, 51.2", target = "Dinn (Rare Elite, Zaqali Caldera)", cost = "Free", difficulty = "Medium", guide = "1. Enter Zaralek Cavern via the cave between the Ohn'ahran Plains and Valdrakken.\n2. Fly to the Zaqali Caldera in the southwest of the cavern.\n3. Find and kill the rare elite Dinn.\n4. Loot Dinn's Drum from his corpse.", waypoint = "/way Zaralek Cavern 28.5 51.2 Dinn" },
    [210411] = { name = "Fast Growing Seed", sourceType = "TREASURE", zone = "Emerald Dream", coords = "37.3, 30.7", target = "Pineshrew Cache", cost = "Free", difficulty = "Very Easy", guide = "1. Travel to the Emerald Dream (portal from the Dream Wardens or Amirdrassil area).\n2. Fly to the Pineshrew Cache location.\n3. Loot the Pineshrew Cache to get the Fast Growing Seed.", waypoint = "/way Emerald Dream 37.3 30.7 Pineshrew Cache" },
    [201927] = { name = "Gleaming Arcanocrystal", sourceType = "TREASURE", zone = "The Azure Span", coords = "45.1, 59.4", target = "Forgotten Jewel Box", cost = "Free", difficulty = "Easy", guide = "1. Fly to the Forgotten Jewel Box spot in the middle of The Azure Span.\n2. Loot the Forgotten Jewel Box (Treasures of The Azure Span criteria).\n3. The Gleaming Arcanocrystal is inside.", waypoint = "/way The Azure Span 45.1 59.4 Forgotten Jewel Box" },
    [206993] = { name = "Investi-gator's Pocketwatch", sourceType = "LOOT", zone = "Thaldraszus", coords = "54.6, 85.9", target = "Temporal Investi-gator (Rare, Eon's Fringe)", cost = "Free", difficulty = "Medium", guide = "1. Complete Melly Teletone's questline in Thaldraszus, starting with 'Time, Signature' and finishing 'Feats Per Minute'.\n2. The rare Temporal Investi-gator then spawns in Eon's Fringe.\n3. Kill it and loot the Investi-gator's Pocketwatch.", waypoint = "/way Thaldraszus 54.6 85.9 Temporal Investi-gator" },
    [199899] = { name = "Iskaara Tug Sled", sourceType = "VENDOR", zone = "The Azure Span", coords = "13.1, 49.3", target = "Kiopo / Murik (Iskaara)", cost = "400 Dragon Isles Supplies + 5 gold (Iskaara Tuskarr Renown 26)", difficulty = "Medium", guide = "1. Reach Renown 26 with the Iskaara Tuskarr.\n2. Travel to Iskaara village in the southwest of The Azure Span.\n3. Buy the Iskaara Tug Sled from Kiopo (next to the big soup pot) or the quartermaster Murik.", waypoint = "/way The Azure Span 13.1 49.3 Kiopo (Iskaara)" },
    [198090] = { name = "Jar of Excess Slime", sourceType = "QUEST", zone = "The Azure Span", coords = "13.0, 22.7", target = "Root of Decay (quest 'One Bad Apple')", cost = "Free", difficulty = "Easy", guide = "1. Pick up the quest 'One Bad Apple' from Gnoll Mon-Ark at 16.2, 20.9.\n2. Go to the Rotting Root near the first cage at 13.0, 22.7 and pull it.\n3. Kill the spawned Root of Decay.\n4. Turn in the quest to receive the Jar of Excess Slime.", waypoint = "/way The Azure Span 13.0 22.7 Root of Decay" },
    [202711] = { name = "Lost Compass", sourceType = "TREASURE", zone = "The Azure Span", coords = "74.9, 55.0", target = "Lost Compass (Lonely Falls)", cost = "Free", difficulty = "Very Easy", guide = "1. Fly to the Lonely Falls in eastern The Azure Span.\n2. Loot the Lost Compass treasure object on the ground.\n3. The toy is added to your toy box.", waypoint = "/way The Azure Span 74.9 55.0 Lost Compass" },
    [198827] = { name = "Magical Snow Sled", sourceType = "VENDOR", zone = "The Azure Span", coords = "13.1, 49.3", target = "Kiopo / Murik (Iskaara)", cost = "400 Dragon Isles Supplies + 5 gold (Iskaara Tuskarr Renown 26)", difficulty = "Medium", guide = "1. Reach Renown 26 with the Iskaara Tuskarr.\n2. Travel to Iskaara village in the southwest of The Azure Span.\n3. Buy the Magical Snow Sled from Kiopo or the quartermaster Murik.", waypoint = "/way The Azure Span 13.1 49.3 Kiopo (Iskaara)" },
    [205463] = { name = "Molten Lava Ball", sourceType = "LOOT", zone = "Emerald Dream", coords = "45.8, 18.8", target = "Moltenbinder's Disciple (Rare, Slagfell Hold)", cost = "Free", difficulty = "Medium", guide = "1. Enter the Emerald Dream zone.\n2. Fly to Slagfell Hold in the northwest of the zone.\n3. Find and kill the rare djaradin Moltenbinder's Disciple.\n4. Loot the Molten Lava Ball.", waypoint = "/way Emerald Dream 45.8 18.8 Moltenbinder's Disciple" },
    [205796] = { name = "Molten Lava Pack", sourceType = "LOOT", zone = "Zaralek Cavern", coords = "45.7, 33.3", target = "Invoq (Rare Elite, Battlefield Ruins)", cost = "Free", difficulty = "Medium", guide = "1. Enter Zaralek Cavern.\n2. Fly to the Battlefield Ruins by the lava river.\n3. Kill the rare elite Invoq (daily elite world quest).\n4. Loot the Molten Lava Pack.", waypoint = "/way Zaralek Cavern 45.7 33.3 Invoq" },
    [200160] = { name = "Notfar's Favorite Food", sourceType = "LOOT", zone = "The Azure Span", coords = "20.6, 49.4", target = "Notfar the Unbearable (Rare, southern shore cave)", cost = "Free", difficulty = "Easy", guide = "1. Fly to the cave on the southern shore of The Azure Span.\n2. Enter the cave and find the rare furbolg Notfar the Unbearable.\n3. Kill him and loot Notfar's Favorite Food.", waypoint = "/way The Azure Span 20.6 49.4 Notfar the Unbearable" },
    [210725] = { name = "Owl Post", sourceType = "TREASURE", zone = "Emerald Dream", coords = "47.5, 34.9", target = "Hidden Moonkin Stash (floating tree, Haven Cascades)", cost = "Free", difficulty = "Easy", guide = "1. Enter the Emerald Dream and fly to the Haven Cascades.\n2. Fly up on top of the floating tree root.\n3. Loot the Hidden Moonkin Stash to get the Owl Post.", waypoint = "/way Emerald Dream 47.5 34.9 Hidden Moonkin Stash" },
    [224783] = { name = "Sovereign's Finery Chest", sourceType = "TREASURE", zone = "The Ringing Deeps", coords = "52.1, 53.1", target = "Forgotten Treasure (cave in the Cataract River)", cost = "Free", difficulty = "Easy", guide = "1. Travel to The Ringing Deeps (level 73+).\n2. Enter the cave in the Cataract River.\n3. Open the nearby chests to get the Forgotten Key.\n4. Use the key and loot the Forgotten Treasure for the Sovereign's Finery Chest.", waypoint = "/way The Ringing Deeps 52.1 53.1 Forgotten Treasure" },
    [200999] = { name = "The Super Shellkhan Gang", sourceType = "LOOT", zone = "Thaldraszus", coords = "38.5, 68.4", target = "The Great Shellkhan (Rare, The Cascades)", cost = "Free", difficulty = "Medium", guide = "1. Pick up the Case of Fresh Gleamfish near the Azure Archives.\n2. Quickly fly to The Cascades and deliver the fish to Patient Vaargo next to the dormant turtle (item lasts 15 minutes).\n3. The Great Shellkhan wakes up and becomes attackable.\n4. Kill it and loot The Super Shellkhan Gang.", waypoint = "/way Thaldraszus 38.5 68.4 The Great Shellkhan" },
    [202253] = { name = "Primal Stave of Claw and Fur", sourceType = "VENDOR", zone = "The Azure Span", coords = "65.8, 12.7", target = "Kazzi (Winterpelt Furbolg quartermaster, Winterpelt Hollow)", cost = "400 Dragon Isles Supplies (Winterpelt Furbolg Exalted)", difficulty = "Farm", guide = "1. Reach Exalted with the Winterpelt Furbolg (complete the Winterpelt Hollow questline).\n2. Fly to Winterpelt Hollow in northeastern The Azure Span.\n3. Buy the Primal Stave of Claw and Fur from the quartermaster Kazzi.", waypoint = "/way The Azure Span 65.8 12.7 Kazzi (Winterpelt Hollow)" },

    ---------------------------------------------------------------------------
