    [46843] = { name = "Argent Crusader's Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.4, 23.2", target = "Dame Evniki Kapsalis (Argent Pavilion)", cost = "15 Champion's Seals (Crusader title required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in northeastern Icecrown.\n2. Earn the Crusader title by becoming Champion of all five faction cities.\n3. Speak with Dame Evniki Kapsalis in the Argent Pavilion at 69.4, 23.2.\n4. Purchase the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.4 23.2 Dame Evniki Kapsalis (Argent Pavilion)" },
    [45011] = { name = "Stormwind Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Corporal Arthur Flew (Stormwind Pavilion)", cost = "15 Champion's Seals (Champion of Stormwind required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Stormwind.\n3. Find Corporal Arthur Flew in the Stormwind pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Corporal Arthur Flew (Stormwind Pavilion)" },
    [45013] = { name = "Thunder Bluff Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Doru Thunderhorn (Thunder Bluff Pavilion)", cost = "15 Champion's Seals (Champion of Thunder Bluff required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Thunder Bluff.\n3. Find Doru Thunderhorn in the Thunder Bluff pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Doru Thunderhorn (Thunder Bluff Pavilion)" },
    [45014] = { name = "Orgrimmar Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Freka Bloodaxe (Orgrimmar Pavilion)", cost = "15 Champion's Seals (Champion of Orgrimmar required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Orgrimmar.\n3. Find Freka Bloodaxe in the Orgrimmar pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Freka Bloodaxe (Orgrimmar Pavilion)" },
    [45015] = { name = "Sen'jin Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Samamba (Sen'jin Pavilion)", cost = "15 Champion's Seals (Champion of Darkspear Trolls required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of the Darkspear Trolls.\n3. Find Samamba in the Sen'jin pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Samamba (Sen'jin Pavilion)" },
    [45016] = { name = "Undercity Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Eliza Killian (Undercity Pavilion)", cost = "15 Champion's Seals (Champion of Undercity required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Undercity.\n3. Find Eliza Killian in the Undercity pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Eliza Killian (Undercity Pavilion)" },
    [45017] = { name = "Silvermoon City Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Trellis Morningsun (Silvermoon Pavilion)", cost = "15 Champion's Seals (Champion of Silvermoon City required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Silvermoon City.\n3. Find Trellis Morningsun in the Silvermoon pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Trellis Morningsun (Silvermoon Pavilion)" },
    [45018] = { name = "Ironforge Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Derrick Brindlebeard (Ironforge Pavilion)", cost = "15 Champion's Seals (Champion of Ironforge required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Ironforge.\n3. Find Derrick Brindlebeard in the Ironforge pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Derrick Brindlebeard (Ironforge Pavilion)" },
    [45019] = { name = "Gnomeregan Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Rillie Spindlenut (Gnomeregan Pavilion)", cost = "15 Champion's Seals (Champion of Gnomeregan Exiles required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of the Gnomeregan Exiles.\n3. Find Rillie Spindlenut in the Gnomeregan pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Rillie Spindlenut (Gnomeregan Pavilion)" },
    [45020] = { name = "Exodar Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Irisee (Exodar Pavilion)", cost = "15 Champion's Seals (Champion of Exodar required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Exodar.\n3. Find Irisee in the Exodar pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Irisee (Exodar Pavilion)" },
    [45021] = { name = "Darnassus Banner", sourceType = "VENDOR", zone = "Icecrown", coords = "69.6, 22.8", target = "Rook Hawkfist (Darnassus Pavilion)", cost = "15 Champion's Seals (Champion of Darnassus required)", difficulty = "Easy", guide = "1. Travel to the Argent Tournament Grounds in Icecrown.\n2. Complete Argent Tournament dailies to become Champion of Darnassus.\n3. Find Rook Hawkfist in the Darnassus pavilion and buy the banner for 15 Champion's Seals.", waypoint = "/way Icecrown 69.6 22.8 Rook Hawkfist (Darnassus Pavilion)" },
    [45012] = { name = "Vial of Gorat's Blood", sourceType = "QUEST", zone = "Northern Barrens", coords = "42.7, 15.0", target = "Gorat / Kadrak (Mor'shan Rampart)", cost = "Quest item (Final Report)", difficulty = "Very Easy", guide = "1. Travel to Mor'shan Rampart in Northern Barrens at 42.7, 15.0.\n2. Pick up the quest Final Report from Kadrak.\n3. Obtain the Vial of Gorat's Blood from the fallen assassin Gorat during the quest.\n4. Return the vial to Kadrak to complete the quest.", waypoint = "/way Northern Barrens 42.7 15.0 Mor'shan Rampart (Kadrak)" },
    [45063] = { name = "Foam Sword Rack", sourceType = "OTHER", zone = "Stranglethorn Vale", coords = "27.0, 77.0", target = "Landro Longshot (Booty Bay lower docks)", cost = "WoW TCG promo code or Black Market AH gold", difficulty = "Very Easy", guide = "1. Foam Sword Rack originates from the WoW TCG Blood of Gladiators set.\n2. Redeem a TCG promotion code and exchange the in-game code with Landro Longshot.\n3. Landro Longshot stands on the lower docks of Booty Bay at 27.0, 77.0.\n4. The rack also appears on the Black Market Auction House for gold.", waypoint = "/way Stranglethorn Vale 27.0 77.0 Landro Longshot (Booty Bay docks)" },
    [54651] = { name = "Gnomeregan Pride", sourceType = "EVENT", zone = "Dun Morogh", coords = "53.7, 52.2", target = "Captain Tread Sparknozzle (Steelgrill's Depot)", cost = "Quest reward (event no longer available)", difficulty = "Very Easy", guide = "1. During the Operation: Gnomeregan world event, complete the quest chain in Dun Morogh.\n2. Turn in Words for Delivery to Captain Tread Sparknozzle at Steelgrill's Depot (53.7, 52.2).\n3. Completing the event quest chain rewarded this toy.\n4. Note: the event has ended and the item is no longer obtainable.", waypoint = "/way Dun Morogh 53.7 52.2 Steelgrill's Depot" },
    [54653] = { name = "Darkspear Pride", sourceType = "EVENT", zone = "Durotar", coords = "55.4, 73.4", target = "Witch Doctor Hez'tok (Sen'jin Village)", cost = "Quest reward (event no longer available)", difficulty = "Very Easy", guide = "1. During the Zalazane's Fall world event, start the quest chain in Sen'jin Village, Durotar.\n2. Talk to Witch Doctor Hez'tok (55.4, 73.4) for Dance Of De Spirits.\n3. Complete the event quest chain up to Zalazane's Fall.\n4. The toy was rewarded for completing the chain. Note: no longer obtainable.", waypoint = "/way Durotar 55.4 73.4 Sen'jin Village (Hez'tok)" },
    [64997] = { name = "Tol Barad Searchlight", sourceType = "VENDOR", zone = "Tol Barad Peninsula", coords = "54.6, 81.0", target = "Pogg (Hellscream's Grasp)", cost = "250 Tol Barad Commendations (Hellscream's Reach Honored)", difficulty = "Easy", guide = "1. Earn Honored reputation with Hellscream's Reach on the Tol Barad Peninsula.\n2. Complete Tol Barad daily quests to collect Tol Barad Commendations.\n3. Travel to Hellscream's Grasp at 54.6, 81.0.\n4. Buy the searchlight from Pogg for 250 Tol Barad Commendations.", waypoint = "/way Tol Barad Peninsula 54.6 81.0 Pogg (Hellscream's Grasp)" },
    [69775] = { name = "Vrykul Drinking Horn", sourceType = "PROFESSION", zone = "Howling Fjord", coords = "64.4, 47.0", target = "Vrykul Archaeology (digsites, Baleheim area)", cost = "100 Vrykul Archaeology Fragments (Archaeology 375)", difficulty = "Medium", guide = "1. Train Archaeology to 375 skill.\n2. Survey at vrykul digsites in Howling Fjord, Icecrown, The Storm Peaks and Grizzly Hills.\n3. Collect 100 Vrykul Archaeology Fragments.\n4. Solve the rare Vrykul Drinking Horn project to learn the toy.", waypoint = "/way Howling Fjord 64.4 47.0 Baleheim vrykul digsite area" },
    [129929] = { name = "Ever-Shifting Mirror", sourceType = "VENDOR", zone = "Shattrath City", coords = "54.0, 39.0", target = "Cupri (Terrace of Light, upper level)", cost = "500 Timewarped Badges", difficulty = "Easy", guide = "1. Queue for Burning Crusade Timewalking and earn Timewarped Badges.\n2. Travel to Shattrath City and enter the Terrace of Light on the north side.\n3. Find the timewalking vendor Cupri on the upper level at 54.0, 39.0 during the event.\n4. Buy the mirror for 500 Timewarped Badges (requires level 40).", waypoint = "/way Shattrath City 54.0 39.0 Cupri (Terrace of Light)" },
    [134020] = { name = "Chef's Hat", sourceType = "VENDOR", zone = "Dalaran", coords = "40.8, 65.2", target = "Derek Odds (A Hero's Welcome inn, kitchen)", cost = "100 Epicurean's Awards (Northrend Cooking 25 required)", difficulty = "Easy", guide = "1. Learn Northrend Cooking to at least 25 skill.\n2. Complete the cooking daily quests in Dalaran to earn Epicurean's Awards.\n3. Enter the Alliance inn A Hero's Welcome and go to the kitchen area.\n4. Buy the Chef's Hat from Derek Odds for 100 Epicurean's Awards.", waypoint = "/way Dalaran 40.8 65.2 Derek Odds (A Hero's Welcome)" },
    [151016] = { name = "Fractured Necrolyte Skull", sourceType = "VENDOR", zone = "Shattrath City", coords = "54.0, 39.0", target = "Cupri (Terrace of Light, upper level)", cost = "750 Timewarped Badges", difficulty = "Easy", guide = "1. Queue for Burning Crusade Timewalking and earn Timewarped Badges.\n2. Travel to Shattrath City and find Cupri on the upper level of the Terrace of Light at 54.0, 39.0 during the event.\n3. Buy the skull for 750 Timewarped Badges. Using it sacrifices a critter soul to open a portal to the Black Temple.", waypoint = "/way Shattrath City 54.0 39.0 Cupri (Terrace of Light)" },
    [202253] = { name = "Primal Stave of Claw and Fur", sourceType = "VENDOR", zone = "The Azure Span", coords = "65.8, 12.7", target = "Kazzi (Winterpelt Hollow)", cost = "400 Dragon Isles Supplies (Winterpelt Furbolg Exalted)", difficulty = "Medium", guide = "1. Earn Exalted reputation with the Winterpelt Furbolg by doing their quests in Winterpelt Hollow.\n2. Travel to Winterpelt Hollow in northeastern The Azure Span at 65.8, 12.7.\n3. Speak with the quartermaster Kazzi.\n4. Buy the stave for 400 Dragon Isles Supplies. It transforms you into a Winterpelt Furbolg for 5 minutes.", waypoint = "/way The Azure Span 65.8 12.7 Kazzi (Winterpelt Hollow)" },

},

    ---------------------------------------------------------------------------
    -- Dragonflight / Zereth Mortis treasures & rares (verified: WowDB/Wowpedia/warcraft.wiki.gg + HandyNotes/RareScanner data)
    ---------------------------------------------------------------------------
    [190177] = { name = "Sphere of Enlightened Cogitation", sourceType = "OTHER", zone = "Zereth Mortis", coords = "34.8, 64.1", target = "Vilo (Enlightened Broker) - Enlightened Broker Supplies (paragon cache)", cost = "Free (requires paragon reputation with The Enlightened)", difficulty = "Farm", guide = "1. In Zereth Mortis, build reputation with The Enlightened via world quests, the campaign and the daily quest.\n2. Reach Exalted, then keep turning in the repeatable 'Supplies from The Enlightened' quest to Vilo at Haven (34.8, 64.1) to trigger paragon caches.\n3. Loot the Enlightened Broker Supplies cache - the Sphere of Enlightened Cogitation has a chance to be inside.", waypoint = "/way Zereth Mortis 34.8 64.1 Vilo" },
    [190457] = { name = "Protopological Cube", sourceType = "TREASURE", zone = "Zereth Mortis", coords = "77.5, 58.2", target = "Syntactic Vault (cave on the island east of Haven)", cost = "Free", difficulty = "Easy", guide = "1. Fly to the island east of Haven in Zereth Mortis and enter the cave at 77.5, 58.2 where the Syntactic Vault stands.\n2. Touch the 6 glowing Runic Syllables on the pillars around the island to gain 6 stacks of Syllabic Recall.\n3. With 6 stacks active, interact with the Syntactic Seal to dispel it and open the vault.\n4. Loot the Syntactic Vault to obtain the Protopological Cube.", waypoint = "/way Zereth Mortis 77.5 58.2 Syntactic Vault" },
    [200160] = { name = "Notfar's Favorite Food", sourceType = "LOOT", zone = "The Azure Span", coords = "20.6, 49.4", target = "Notfar the Unbearable (rare furbolg in a cave) - loot the Gutrot Slime he expels at ~20% health", cost = "Free", difficulty = "Easy", guide = "1. Fly to the cave on the southern shore of The Azure Span at 20.6, 49.4.\n2. Engage the rare furbolg Notfar the Unbearable inside the cave.\n3. At around 20% health he expels a Gutrot Slime - kill it and loot Notfar's Favorite Food.", waypoint = "/way The Azure Span 20.6 49.4 Notfar the Unbearable" },
    [202022] = { name = "Yennu's Kite", sourceType = "TREASURE", zone = "The Waking Shores", coords = "46.8, 31.2", target = "Yennu's Kite (treasure object at the Crumbling Cliffs)", cost = "Free", difficulty = "Very Easy", guide = "1. Fly to the Crumbling Cliffs in the south of The Waking Shores, at 46.8, 31.2.\n2. Look for the kite hanging just below the cliff edge near the water.\n3. Loot the Yennu's Kite treasure object to learn the toy.", waypoint = "/way The Waking Shores 46.8 31.2 Yennu's Kite" },
    [202042] = { name = "Aquatic Shades", sourceType = "VENDOR", zone = "Ohn'ahran Plains", coords = "82.3, 73.2", target = "The Great Swog (NPC in a cave at the Roaring Dragonsprings)", cost = "1 Gold Coin of the Isles (for the Immaculate Sac of Swog Treasures)", difficulty = "Medium", guide = "1. Fish in Dragon Isles waters to collect Copper Coins of the Isles.\n2. Trade up 100 Copper Coins for 1 Silver Coin, then 100 Silver for 1 Gold Coin of the Isles.\n3. Travel to The Great Swog in the cave at the Roaring Dragonsprings, Ohn'ahran Plains (82.3, 73.2).\n4. Buy the Immaculate Sac of Swog Treasures for 1 Gold Coin and open it to receive the Aquatic Shades.", waypoint = "/way Ohn'ahran Plains 82.3 73.2 The Great Swog" },

    ---------------------------------------------------------------------------
    -- TWW / Khaz Algar II — corrected + new verified entries (some replace wrong IDs from the original DB)
    ---------------------------------------------------------------------------
    [219387] = { name = "Barrel of Fireworks", sourceType = "PROFESSION", zone = "Dornogal", coords = "49.0, 56.0", target = "Thermalseer Arhdas (Engineering Trainer) / Tinker's Workbench", cost = "50 Pile of Rusted Scrap + tools", difficulty = "Easy", guide = "1. Learn Khaz Algar Engineering (level 68+) from Thermalseer Arhdas in the Foregrounds, Dornogal.\n2. Learn the Barrel of Fireworks recipe through Inventing (Discovery) or a Notes item.\n3. Craft it at a Tinker's Workbench using 50 Pile of Rusted Scrap and the required tools.\n4. Use the toy to deploy a barrel of fireworks for 5 min (60 min cooldown).", waypoint = "/way Dornogal 49.0 56.0 Engineering Trainer" },
    [221966] = { name = "Wormhole Generator: Khaz Algar", sourceType = "PROFESSION", zone = "Dornogal", coords = "49.0, 56.0", target = "Thermalseer Arhdas (Engineering Trainer) / Tinker's Workbench", cost = "50 Pile of Rusted Scrap", difficulty = "Easy", guide = "1. Learn Khaz Algar Engineering (level 68+) from the trainer in Dornogal.\n2. Obtain the Prototype: Wormhole Generator: Khaz Algar (Inventing/Notes discovery) to learn the recipe.\n3. Craft it at a Tinker's Workbench with 50 Pile of Rusted Scrap.\n4. Use the toy to open a wormhole to a random location in Khaz Algar (30 min cooldown, requires level 68).", waypoint = "/way Dornogal 49.0 56.0 Engineering Trainer" },
    [224552] = { name = "Cave Spelunker's Torch", sourceType = "TREASURE", zone = "Hallowfall", coords = "58.4, 27.2", target = "Illuminated Footlocker", cost = "Free", difficulty = "Easy", guide = "1. Enter the dark cave in northeastern Hallowfall (cave entrance 57.5, 27.4).\n2. Chase the Starblessed Glimmerfly and collect 5 Star Glimmer stacks to gain the Glimmering Illumination buff (2 min).\n3. With the buff active, the Illuminated Footlocker becomes visible on the cave floor at 58.4, 27.2.\n4. Loot the footlocker to learn the toy.", waypoint = "/way Hallowfall 58.4 27.2 Illuminated Footlocker" },
    [224554] = { name = "Silver Linin' Scepter", sourceType = "TREASURE", zone = "Hallowfall", coords = "45.9, 45.1", target = "Sunken Cache", cost = "Free", difficulty = "Medium", guide = "1. Find and talk to the four Sky Captains (Clairmonte, Dornald, Onaro, Aerthin) aboard the zeppelins patrolling Hallowfall.\n2. After speaking to all four, the Sunken Cache is revealed underwater off the coast of Mereldar.\n3. Dive at 45.9, 45.1 and loot the Sunken Cache to learn the toy.", waypoint = "/way Hallowfall 45.9 45.1 Sunken Cache" },
    [224783] = { name = "Sovereign's Finery Chest", sourceType = "TREASURE", zone = "The Ringing Deeps", coords = "52.0, 53.1", target = "Forgotten Treasure", cost = "Free", difficulty = "Medium", guide = "1. Enter the cave behind the waterfall in the Cataract River (entrance 52.0, 53.1).\n2. Open the five regular chests in the room until you find the Forgotten Key.\n3. Use the Forgotten Key on the Forgotten Treasure chest.\n4. Loot it to learn the toy.", waypoint = "/way The Ringing Deeps 52.0 53.1 Forgotten Treasure cave" },
    [225659] = { name = "Arathi Book Collection", sourceType = "TREASURE", zone = "Hallowfall", coords = "40.0, 51.2", target = "Loremaster's Reward (Ryfus Sacredpyr)", cost = "Free", difficulty = "Medium", guide = "1. Go to the Church of the Sacred Flame in Mereldar, Hallowfall, and talk to Ryfus Sacredpyr (40.0, 51.1).\n2. Answer his six lore questions correctly (the answers are in six books scattered around Hallowfall).\n3. Once all answers are correct, the Loremaster's Reward appears on the table beside him (40.0, 51.2).\n4. Loot it to learn the toy.", waypoint = "/way Hallowfall 40.0 51.2 Loremaster's Reward" },
    [225969] = { name = "Forged Flag of Victory", sourceType = "VENDOR", zone = "Dornogal", coords = "55.2, 76.9", target = "Gilderann", cost = "1,500 Bloody Tokens", difficulty = "Medium", guide = "1. Travel to the Contender's Gate in Dornogal.\n2. Find Gilderann, the Bloody Tokens PvP vendor, at 55.2, 76.9.\n3. Earn Bloody Tokens from PvP activities.\n4. Buy the Forged Flag of Victory for 1,500 Bloody Tokens.", waypoint = "/way Dornogal 55.2 76.9 Gilderann" },
    [228698] = { name = "Candleflexer's Dumbbell", sourceType = "VENDOR", zone = "The Ringing Deeps", coords = "47.3, 32.9", target = "Waxmonger Squick", cost = "5,000 Resonance Crystals (Renown 18 with The Assembly of the Deeps)", difficulty = "Farm", guide = "1. Reach Renown 18 with The Assembly of the Deeps.\n2. Travel to Gundargaz in The Ringing Deeps and find the quartermaster Waxmonger Squick at 47.3, 32.9.\n3. Buy the Candleflexer's Dumbbell for 5,000 Resonance Crystals.\n4. Use it outdoors to summon Lil Wick to carry you around (60 min cooldown).", waypoint = "/way The Ringing Deeps 47.3 32.9 Waxmonger Squick" },
    [228705] = { name = "Arachnoserum", sourceType = "VENDOR", zone = "Azj-Kahet", coords = "55.3, 41.2", target = "Lady Vinazian (Severed Threads Quartermaster)", cost = "1,750 Kej (Renown 17 with The Severed Threads)", difficulty = "Farm", guide = "1. Reach Renown 17 with The Severed Threads.\n2. Go to The Weaver's Lair in Azj-Kahet and find the quartermaster Lady Vinazian at 55.3, 41.2.\n3. Buy the Arachnoserum for 1,750 Kej.\n4. Use the toy to morph into a giant spider (60 min cooldown).", waypoint = "/way Azj-Kahet 55.3 41.2 Lady Vinazian" },
    [228940] = { name = "Notorious Thread's Hearthstone", sourceType = "VENDOR", zone = "Azj-Kahet", coords = "55.2, 41.4", target = "Yamas the Provider", cost = "3,000 Kej", difficulty = "Farm", guide = "1. Prove yourself to The Severed Threads (high Renown) in Azj-Kahet.\n2. Go to The Weaver's Lair and find Yamas the Provider next to the quartermaster at 55.2, 41.4.\n3. Buy the Notorious Thread's Hearthstone for 3,000 Kej.\n4. Use it like a Hearthstone to return to your home location.", waypoint = "/way Azj-Kahet 55.2 41.4 Yamas the Provider" },
    [230850] = { name = "Delve-O-Bot 7001", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 45.0", target = "Reno Jackson", cost = "5,000 Resonance Crystals", difficulty = "Medium", guide = "1. Travel to the Delver's Headquarters in central Dornogal.\n2. Find Reno Jackson at 47.6, 45.0.\n3. Buy the Delve-O-Bot 7001 for 5,000 Resonance Crystals.\n4. Use it to call down a bot that carries you to a random Bountiful Delve (completing one resets the 60 min cooldown).", waypoint = "/way Dornogal 47.6 45.0 Reno Jackson" },
    [238852] = { name = "Flame's Radiance Banner", sourceType = "VENDOR", zone = "Hallowfall", coords = "28.0, 56.0", target = "Lars Bronsmaelt", cost = "5,000 Resonance Crystals (Renown 4 with Flame's Radiance)", difficulty = "Easy", guide = "1. Reach Renown 4 with Flame's Radiance (Nightfall scenario in west Hallowfall).\n2. Go to Morgaen's Tears in southwestern Hallowfall and find Lars Bronsmaelt at 28.0, 56.0.\n3. Buy the Flame's Radiance Banner for 5,000 Resonance Crystals.\n4. Use it to plant a banner for the Flame's Radiance (10 min cooldown).", waypoint = "/way Hallowfall 28.0 56.0 Lars Bronsmaelt" },
    [243056] = { name = "Delver's Mana-Bound Ethergate", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 45.0", target = "Reno Jackson", cost = "10 Resonance Crystals (Delver's Journey Tier 7+)", difficulty = "Easy", guide = "1. Reach Tier 7+ of the Delver's Journey (delve achievements).\n2. Go to the Delver's Headquarters in Dornogal and find Reno Jackson at 47.6, 45.0.\n3. Buy the Delver's Mana-Bound Ethergate for 10 Resonance Crystals.\n4. Use it to open a 60 sec portal that any player can use to return to the Explorers' League home base in Dornogal (2 hr cooldown).", waypoint = "/way Dornogal 47.6 45.0 Reno Jackson" },
    [244792] = { name = "Etheric Brannmorpher", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 45.0", target = "Reno Jackson", cost = "10 Resonance Crystals (Delver's Journey Tier 10+)", difficulty = "Easy", guide = "1. Reach Tier 10+ of the Delver's Journey.\n2. Go to the Delver's Headquarters in Dornogal and find Reno Jackson at 47.6, 45.0.\n3. Buy the Etheric Brannmorpher for 10 Resonance Crystals.\n4. Use it to summon an Ethereal Transmorpher that changes your appearance for 60 min (60 min cooldown).", waypoint = "/way Dornogal 47.6 45.0 Reno Jackson" },

    ----------------------------------------------------------------------------
    -- TWW (11.x) — verified guides batch v1.9.3 (Dornogal / Hallowfall / Undermine / K'aresh vendors)
    ----------------------------------------------------------------------------
    [211931] = { name = "Abyss Caller Horn", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 43.6", target = "Sir Finley Mrrgglton (Delver's Headquarters)", cost = "500 Undercoin", difficulty = "Easy", guide = "1. Travel to Dornogal, the capital city of Khaz Algar (Isle of Dorn).\n2. Head to the Delver's Headquarters in central Dornogal at 47.6, 43.6 (between the Forgegrounds and Keepers Terrace).\n3. Find Sir Finley Mrrgglton and buy the Abyss Caller Horn for 500 Undercoin.\n4. Undercoins are earned from delve quests and bounties.\n5. Use the horn to conjure a body of water (1 hour cooldown).", waypoint = "/way Dornogal 47.6 43.6 Sir Finley Mrrgglton (Delver's HQ)" },
    [225910] = { name = "Pileus Delight", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 43.6", target = "Sir Finley Mrrgglton (Delver's Headquarters)", cost = "500 Undercoin", difficulty = "Easy", guide = "1. Go to the Delver's Headquarters in Dornogal at 47.6, 43.6.\n2. Speak with Sir Finley Mrrgglton (the murloc delve quartermaster).\n3. Purchase the Pileus Delight for 500 Undercoin.\n4. Use it to summon a delightful pileus mushroom (10 min cooldown).", waypoint = "/way Dornogal 47.6 43.6 Sir Finley Mrrgglton (Delver's HQ)" },
    [230924] = { name = "Spotlight Materializer 1000", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 43.6", target = "Sir Finley Mrrgglton (Delver's Headquarters)", cost = "500 Undercoin", difficulty = "Easy", guide = "1. Fly to Dornogal and enter the Delver's Headquarters at 47.6, 43.6.\n2. Find Sir Finley Mrrgglton next to Brann Bronzebeard.\n3. Buy the Spotlight Materializer 1000 for 500 Undercoin.\n4. Use it to put yourself in the spotlight (5 min cooldown).", waypoint = "/way Dornogal 47.6 43.6 Sir Finley Mrrgglton (Delver's HQ)" },
    [231064] = { name = "Throwaway Gangster Disguise", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 43.6", target = "Sir Finley Mrrgglton (Delver's Headquarters)", cost = "2,500 Undercoin", difficulty = "Easy", guide = "1. Travel to the Delver's Headquarters in Dornogal at 47.6, 43.6.\n2. Talk to Sir Finley Mrrgglton.\n3. Purchase the Throwaway Gangster Disguise for 2,500 Undercoin.\n4. Use it to equip a gangster disguise (30 min cooldown).", waypoint = "/way Dornogal 47.6 43.6 Sir Finley Mrrgglton (Delver's HQ)" },
    [235016] = { name = "Redeployment Module", sourceType = "VENDOR", zone = "Dornogal", coords = "47.6, 43.6", target = "Sir Finley Mrrgglton (Delver's Headquarters)", cost = "5,000 Undercoin", difficulty = "Easy", guide = "1. Go to the Delver's Headquarters in Dornogal at 47.6, 43.6.\n2. Speak with Sir Finley Mrrgglton.\n3. Buy the Redeployment Module for 5,000 Undercoin.\n4. Use it to teleport to a nearby delve entrance (daily cooldown).", waypoint = "/way Dornogal 47.6 43.6 Sir Finley Mrrgglton (Delver's HQ)" },
    [228706] = { name = "Rockslidomancer's Stone", sourceType = "VENDOR", zone = "Dornogal", coords = "39.2, 24.3", target = "Auditor Balwurz (Foundation Hall, Council of Dornogal Renown vendor)", cost = "5,000 Resonance Crystals", difficulty = "Easy", guide = "1. Travel to Dornogal and head to the Foundation Hall (north of The Coreway) at 39.2, 24.3.\n2. Find Auditor Balwurz, the Council of Dornogal Renown quartermaster.\n3. Purchase the Rockslidomancer's Stone for 5,000 Resonance Crystals.\n4. Resonance Crystals drop from world activities in Khaz Algar.\n5. Use the stone to turn to stone (60 min cooldown).", waypoint = "/way Dornogal 39.2 24.3 Auditor Balwurz (Foundation Hall)" },
    [228707] = { name = "Trial of Burning Light", sourceType = "VENDOR", zone = "Hallowfall", coords = "41.3, 53.0", target = "Auralia Steelstike (Mereldar, Hallowfall Arathi Renown quartermaster)", cost = "5,000 Resonance Crystals (requires Renown 17 with Hallowfall Arathi)", difficulty = "Easy", guide = "1. Fly to Mereldar in Hallowfall at 41.3, 53.0.\n2. Find Auralia Steelstrike, the Hallowfall Arathi quartermaster, inside the building.\n3. Requires Renown rank 17 with the Hallowfall Arathi.\n4. Buy the Trial of Burning Light for 5,000 Resonance Crystals.\n5. Use it to manifest a trial of light (2 hour cooldown).", waypoint = "/way Hallowfall 41.3 53.0 Auralia Steelstrike (Mereldar)" },
    [238850] = { name = "Arathi Entertainer's Flame", sourceType = "VENDOR", zone = "Hallowfall", coords = "28.3, 56.2", target = "Lars Bronsmaelt (Flame's Radiance quartermaster, west of Mereldar)", cost = "5,000 Resonance Crystals", difficulty = "Easy", guide = "1. Travel to Hallowfall and head west of Mereldar to the Veneration Grounds at 28.3, 56.2.\n2. Find Lars Bronsmaelt, the Flame's Radiance quartermaster.\n3. Purchase the Arathi Entertainer's Flame for 5,000 Resonance Crystals.\n4. Use it to light a festive flame (30 min cooldown).", waypoint = "/way Hallowfall 28.3 56.2 Lars Bronsmaelt (Flame's Radiance)" },
    [239693] = { name = "Radiant Lynx Whistle", sourceType = "VENDOR", zone = "Hallowfall", coords = "28.3, 56.2", target = "Lars Bronsmaelt (Flame's Radiance quartermaster, west of Mereldar)", cost = "5,000 Resonance Crystals", difficulty = "Easy", guide = "1. Go to Hallowfall, west of Mereldar at 28.3, 56.2.\n2. Speak with Lars Bronsmaelt (Flame's Radiance vendor).\n3. Buy the Radiant Lynx Whistle for 5,000 Resonance Crystals.\n4. Use the whistle to summon a radiant lynx (10 min cooldown).", waypoint = "/way Hallowfall 28.3 56.2 Lars Bronsmaelt (Flame's Radiance)" },
    [228914] = { name = "Arachnophile Spectacles", sourceType = "VENDOR", zone = "City of Threads", coords = "46.5, 42.0", target = "Alvus Valavulu (City of Threads vendor)", cost = "1,500 Kej", difficulty = "Easy", guide = "1. Travel to the City of Threads zone in Azj-Kahet, Khaz Algar.\n2. Find Alvus Valavulu in the city at approximately 46.5, 42.0.\n3. Purchase the Arachnophile Spectacles for 1,500 Kej.\n4. Kej is the City of Threads zone currency earned from quests and rares.\n5. Use the spectacles to see the world through spider eyes (5 min cooldown).", waypoint = "/way City of Threads 46.5 42.0 Alvus Valavulu" },
    [226373] = { name = "Everlasting Noggenfogger Elixir", sourceType = "VENDOR", zone = "Undermine", coords = "42.0, 55.0", target = "Lab Assistant Laszly (Undermine cartel quartermaster area)", cost = "5,000 Resonance Crystals", difficulty = "Easy", guide = "1. Enter Undermine (accessible via portal in Dornogal or flying from Isle of Dorn).\n2. Find Lab Assistant Laszly in the cartel area at approximately 42.0, 55.0.\n3. Buy the Everlasting Noggenfogger Elixir for 5,000 Resonance Crystals.\n4. Use it to shrink yourself permanently for 10 minutes (no cooldown).", waypoint = "/way Undermine 42.0 55.0 Lab Assistant Laszly" },
    [234950] = { name = "Atomic Regoblinator", sourceType = "VENDOR", zone = "Undermine", coords = "27.0, 78.0", target = "Sitch Lowdown (Darkfuse Solutions quartermaster, sewers of Hovel Hill)", cost = "5,000 Resonance Crystals (requires Honored with Darkfuse Solutions)", difficulty = "Medium", guide = "1. Travel to Undermine and progress the 'Diversified Investments' quest to unlock the Darkfuse Solutions reputation.\n2. Reach Honored reputation with Darkfuse Solutions.\n3. Find Sitch Lowdown in the sewers of Hovel Hill at approximately 27.0, 78.0.\n4. Purchase the Atomic Regoblinator for 5,000 Resonance Crystals.\n5. Use it to deploy a device that goblinates anyone on it (12 hour cooldown).", waypoint = "/way Undermine 27.0 78.0 Sitch Lowdown (Hovel Hill sewers)" },
    [235670] = { name = "Bilgewater Cartel Banner", sourceType = "VENDOR", zone = "Undermine", coords = "42.0, 55.0", target = "Rocco Razzboom (Undermine)", cost = "Varies (cartel supplies)", difficulty = "Easy", guide = "1. Enter Undermine and find Rocco Razzboom in the cartel hub at approximately 42.0, 55.0.\n2. Purchase the Bilgewater Cartel Banner from him.\n3. Use it to place a Bilgewater Cartel banner (10 min cooldown).", waypoint = "/way Undermine 42.0 55.0 Rocco Razzboom" },
    [246903] = { name = "Guise of the Phase Diver", sourceType = "VENDOR", zone = "K'aresh", coords = "41.0, 62.0", target = "Shad'anis (Overlook Zo'Shuul, K'aresh phase vendor)", cost = "3 Untethered Coin", difficulty = "Easy", guide = "1. Travel to K'aresh (unlocked in Patch 11.2, accessible via portal in Dornogal).\n2. Head to Overlook Zo'Shuul at approximately 41.0, 62.0.\n3. Find Shad'anis, the phase diving vendor.\n4. Earn Untethered Coins by completing the weekly 'More Than Just a Phase' quest.\n5. Buy the Guise of the Phase Diver for 3 Untethered Coins.\n6. Use it to phase-dive (1 hour cooldown).", waypoint = "/way K'aresh 41.0 62.0 Shad'anis (Overlook Zo'Shuul)" },
    [246907] = { name = "Broker Supply Crate", sourceType = "VENDOR", zone = "K'aresh", coords = "41.0, 62.0", target = "Shad'anis (Overlook Zo'Shuul)", cost = "3 Untethered Coin", difficulty = "Easy", guide = "1. Go to K'aresh and fly to Overlook Zo'Shuul at 41.0, 62.0.\n2. Talk to Shad'anis.\n3. Purchase the Broker Supply Crate for 3 Untethered Coins.\n4. Use it to call in a supply drop (30 min cooldown).", waypoint = "/way K'aresh 41.0 62.0 Shad'anis (Overlook Zo'Shuul)" },
    [234473] = { name = "Soweezi's Comfy Lawn Chair", sourceType = "VENDOR", zone = "Siren Isle", coords = "33.0, 68.0", target = "Soweezi (Flotsam Shoal, Siren Isle)", cost = "750 Flame-Blessed Iron", difficulty = "Easy", guide = "1. Travel to Siren Isle (unlocked during TWW campaign, take the zeppelin from Dornogal).\n2. Head to Flotsam Shoal, the main hub, at approximately 33.0, 68.0.\n3. Find Soweezi the goblin beach vendor.\n4. Buy Soweezi's Comfy Lawn Chair for 750 Flame-Blessed Iron.\n5. Use it to summon a comfy lawn chair (5 min cooldown).", waypoint = "/way Siren Isle 33.0 68.0 Soweezi (Flotsam Shoal)" },
    [233486] = { name = "Hallowfall Supply Cache", sourceType = "VENDOR", zone = "Siren Isle", coords = "33.0, 68.0", target = "Ailenda Hedgemyr (Flotsam Shoal, Siren Isle)", cost = "750 Flame-Blessed Iron", difficulty = "Easy", guide = "1. Go to Siren Isle via the zeppelin from Dornogal.\n2. Travel to Flotsam Shoal at 33.0, 68.0.\n3. Find Ailenda Hedgemyr, the Arathi-themed vendor.\n4. Purchase the Hallowfall Supply Cache for 750 Flame-Blessed Iron.\n5. Use it to summon a supply cache (15 min cooldown).", waypoint = "/way Siren Isle 33.0 68.0 Ailenda Hedgemyr (Flotsam Shoal)" },
    [235015] = { name = "Awakened Supply Crate", sourceType = "VENDOR", zone = "Siren Isle", coords = "33.0, 68.0", target = "Hooded Purveyor (Flotsam Shoal, Siren Isle)", cost = "750 Flame-Blessed Iron", difficulty = "Easy", guide = "1. Fly to Siren Isle (zeppelin from Dornogal).\n2. Go to Flotsam Shoal at 33.0, 68.0.\n3. Find the Hooded Purveyor, the Earthen-themed vendor.\n4. Buy the Awakened Supply Crate for 750 Flame-Blessed Iron.\n5. Use it to summon an awakened crate (10 min cooldown).", waypoint = "/way Siren Isle 33.0 68.0 Hooded Purveyor (Flotsam Shoal)" },
    [230727] = { name = "Explosive Victory", sourceType = "LOOT", zone = "Undermine", coords = "75.0, 25.0", target = "The Underpin (Demolition Dome delve, Tier 8+)", cost = "Free (delve boss drop)", difficulty = "Medium", guide = "1. Enter the Demolition Dome delve in northern Undermine at approximately 75.0, 25.0.\n2. Progress through the delve to Tier 8 or higher.\n3. The Underpin can randomly appear as a special boss in Tier 8+ delves.\n4. Defeat The Underpin.\n5. Loot the Explosive Victory toy from his chest.\n6. Use it to emanate an aura of victory (5 min cooldown).", waypoint = "/way Undermine 75.0 25.0 Demolition Dome entrance" },
    [224585] = { name = "Hanna's Locket", sourceType = "TREASURE", zone = "Isle of Dorn", coords = "59.0, 55.0", target = "Tree's Treasure (hidden treasure in Khaz Algar)", cost = "Free", difficulty = "Medium", guide = "1. Travel to the Isle of Dorn in Khaz Algar.\n2. Find the Tree's Treasure hidden among the trees at approximately 59.0, 55.0.\n3. Interact with the glowing tree to reveal the treasure.\n4. Loot Hanna's Locket.\n5. Use it to summon an ethereal horse that gallops forward (10 min cooldown).", waypoint = "/way Isle of Dorn 59.0 55.0 Tree's Treasure (Hanna's Locket)" },
    [225347] = { name = "Web-Vandal's Spinning Wheel", sourceType = "TREASURE", zone = "Azj-Kahet", coords = "63.0, 38.0", target = "Weaving Supplies (treasure object in Azj-Kahet)", cost = "Free", difficulty = "Medium", guide = "1. Fly to Azj-Kahet in Khaz Algar.\n2. Find the Weaving Supplies object on a large round platform at approximately 63.0, 38.0.\n3. To open it, collect 3 pieces of cloth of different colors hidden near the platform.\n4. Loot the Web-Vandal's Spinning Wheel from the supplies.\n5. Use it to dye nerubian spools (1 min cooldown).", waypoint = "/way Azj-Kahet 63.0 38.0 Weaving Supplies" },
    [225556] = { name = "Ancient Construct", sourceType = "TREASURE", zone = "Khaz Algar", coords = "", target = "Sturdy Chest inside any TWW Delve (one-time per delve)", cost = "Free", difficulty = "Easy", guide = "1. Enter any Delve in Khaz Algar (unlocked at level 70+ in TWW).\n2. Progress through the delve and look for a Sturdy Chest (glowing golden chest).\n3. Sturdy Chests are one-time treasures that can appear in various delve rooms.\n4. Loot the Ancient Construct from the Sturdy Chest.\n5. Use it to summon Icarus the Unbreakable target dummy for 60 seconds.", waypoint = "" },
    [235220] = { name = "Fireworks Hat", sourceType = "TREASURE", zone = "Undermine", coords = "59.8, 53.5", target = "Unexploded Fireworks (on rooftop of Venture Storage building, The Heaps)", cost = "Free", difficulty = "Medium", guide = "1. Travel to Undermine and head to The Heaps area.\n2. Go to the Venture Storage building at 59.8, 53.5.\n3. Climb the long metal staircase to the roof.\n4. Turn right and enter the first building — do not use the interior stairs.\n5. Find and loot the Unexploded Fireworks to get the Fireworks Hat.\n6. Use it to launch fireworks from your head (5 min cooldown).", waypoint = "/way Undermine 59.8 53.5 Venture Storage rooftop (Fireworks Hat)" },
    [234951] = { name = "Uncracked Cold Ones", sourceType = "TREASURE", zone = "Undermine", coords = "55.0, 40.0", target = "Uncracked Cold Ones (treasure object in Undermine)", cost = "Free", difficulty = "Medium", guide = "1. Enter Undermine and explore the cartel areas.\n2. Find the Uncracked Cold Ones treasure object at approximately 55.0, 40.0.\n3. Loot the container to receive the Uncracked Cold Ones toy.\n4. Use it to crack open a cold one (3 min cooldown).", waypoint = "/way Undermine 55.0 40.0 Uncracked Cold Ones" },

    ----------------------------------------------------------------------------
    -- Dragonflight (10.x) — verified guides batch v1.9.3 (vendors & treasures)
    ----------------------------------------------------------------------------
    [198646] = { name = "Ornate Dragon Statue", sourceType = "VENDOR", zone = "The Waking Shores", coords = "47.0, 82.0", target = "Emilia Bellocq (Wingrest Embassy, Dragonscale Basecamp)", cost = "200 gold", difficulty = "Very Easy", guide = "1. Fly to Wingrest Embassy in The Waking Shores at 47.0, 82.0 (Dragonscale Basecamp).\n2. Find Emilia Bellocq next to Toht Twofingers.\n3. Purchase the Ornate Dragon Statue for 200 gold.\n4. Use it to place a perfectly-restored dragon statue (5 min cooldown).", waypoint = "/way The Waking Shores 47.0 82.0 Emilia Bellocq (Wingrest Embassy)" },
    [199900] = { name = "Secondhand Survey Tools", sourceType = "VENDOR", zone = "The Waking Shores", coords = "47.0, 82.0", target = "Emilia Bellocq (Wingrest Embassy)", cost = "5 gold", difficulty = "Very Easy", guide = "1. Go to Wingrest Embassy in The Waking Shores at 47.0, 82.0.\n2. Speak with Emilia Bellocq near the Dragonscale Expedition camp.\n3. Buy the Secondhand Survey Tools for just 5 gold.\n4. Use them to survey the area (10 min cooldown).", waypoint = "/way The Waking Shores 47.0 82.0 Emilia Bellocq (Wingrest Embassy)" },
    [202020] = { name = "Chasing Storm", sourceType = "VENDOR", zone = "Thaldraszus", coords = "51.0, 41.0", target = "Brendormi (Temporal Conflux, Storm's Fury event quartermaster)", cost = "75 Storm's Fury currency + 1,200 Elemental Overflow", difficulty = "Easy", guide = "1. Fly to the Temporal Conflux in Thaldraszus at approximately 51.0, 41.0.\n2. Find Brendormi, the dracthyr quartermaster of the Storm's Fury event.\n3. Complete the 'Coalesced Storm Remnants' introduction quests to unlock her shop.\n4. Purchase the Chasing Storm for 75 event currency and 1,200 Elemental Overflow.\n5. Use it to chase a storm (10 min cooldown).", waypoint = "/way Thaldraszus 51.0 41.0 Brendormi (Temporal Conflux)" },
    [205418] = { name = "Blazing Shadowflame Cinder", sourceType = "TREASURE", zone = "Zaralek Cavern", coords = "28.6, 47.9", target = "Blazing Shadowflame Chest (Zaqali Caldera)", cost = "Free", difficulty = "Easy", guide = "1. Travel to Zaralek Cavern (unlocked during Dragonflight campaign).\n2. Head to the Zaqali Caldera at 28.6, 47.9.\n3. Find the Blazing Shadowflame Chest on a fiery mound.\n4. You can open it easily if you have an old fire-related item, or by clicking it directly.\n5. Loot the Blazing Shadowflame Cinder toy.", waypoint = "/way Zaralek Cavern 28.6 47.9 Blazing Shadowflame Chest (Zaqali Caldera)" },
    [202283] = { name = "Reading Glasses", sourceType = "VENDOR", zone = "The Azure Span", coords = "13.0, 49.0", target = "Kazzi (Winterpelt Furbolg vendor, Russet Turning)", cost = "100 Dragon Isles Supplies (requires Friendly with Winterpelt Furbolg)", difficulty = "Easy", guide = "1. Fly to The Azure Span and head to the Winterpelt Furbolg camp at approximately 13.0, 49.0.\n2. Raise your reputation with the Winterpelt Furbolg to Friendly.\n3. Find Kazzi and buy the Reading Glasses for 100 Dragon Isles Supplies.\n4. Use them to read tiny text (5 min cooldown).", waypoint = "/way The Azure Span 13.0 49.0 Kazzi (Winterpelt Furbolg)" },
    [203734] = { name = "Snow Blanket", sourceType = "VENDOR", zone = "The Azure Span", coords = "13.0, 49.0", target = "Kazzi (Winterpelt Furbolg vendor)", cost = "200 Dragon Isles Supplies (requires Revered with Winterpelt Furbolg)", difficulty = "Medium", guide = "1. Go to The Azure Span and find the Winterpelt Furbolg at 13.0, 49.0.\n2. Earn Revered reputation with the Winterpelt Furbolg.\n3. Purchase the Snow Blanket from Kazzi for 200 Dragon Isles Supplies.\n4. Use it to conjure a warm snow blanket (10 min cooldown).", waypoint = "/way The Azure Span 13.0 49.0 Kazzi (Winterpelt Furbolg)" },
    [209035] = { name = "Hearthstone of the Flame", sourceType = "LOOT", zone = "The Emerald Dream", coords = "52.0, 40.0", target = "Larodar, Keeper of the Flame (Amirdrassil raid boss)", cost = "Free (raid drop)", difficulty = "Medium", guide = "1. Enter the Amirdrassil, the Dream's Hope raid in The Emerald Dream.\n2. Defeat Larodar, Keeper of the Flame (any difficulty).\n3. Loot the Hearthstone of the Flame from his corpse (not guaranteed).\n4. Use it to teleport to a random fire-themed location (1 hour cooldown).", waypoint = "/way The Emerald Dream 52.0 40.0 Amirdrassil entrance" },
    [212518] = { name = "Vial of Endless Draconic Scales", sourceType = "VENDOR", zone = "Valdrakken", coords = "38.0, 50.0", target = "Maztha (Valdrakken) or Dathendrash (Stormwind City / Orgrimmar)", cost = "40 Dragon Isles currency (Dragon Isles Supplies)", difficulty = "Easy", guide = "1. Fly to Valdrakken in Thaldraszus at approximately 38.0, 50.0.\n2. Find Maztha, or go to Dathendrash in Stormwind City (52.0, 62.0) / Orgrimmar (52.0, 41.0).\n3. Purchase the Vial of Endless Draconic Scales for 40 Dragon Isles Supplies.\n4. Use it to gain draconic scales (10 min cooldown).", waypoint = "/way Valdrakken 38.0 50.0 Maztha" },

